const mongoose = require('mongoose');

const connectDatabase = () => {
  const mongoUri = process.env.MONGO_URI || process.env.DB_URL;
  
  if (!mongoUri) {
    console.error('MongoDB connection error: MONGO_URI or DB_URL not found in environment variables');
    process.exit(1);
  }

  mongoose.connect(mongoUri, {
    useNewUrlParser: true,
    useUnifiedTopology: true
  }).then((con) => {
    console.log('MongoDB connected to host: ' + con.connection.host);
  }).catch((err) => {
    console.error('MongoDB connection error:', err.message);
    console.error('Please make sure MongoDB is running on:', mongoUri);
    process.exit(1);
  });

  // Error logging
  mongoose.connection.on('error', err => {
    console.error('DB Error:', err);
  });
};

module.exports = connectDatabase;


